import java.util.concurrent.*;
public class Test extends RecursiveTask<Integer> {
    private int n;
    public Test(int n) {
        this.n = n;
    }
    protected Integer compute() {
        if (n <= 1) return 1;
        Test f1 = new Test(n - 1);
        f1.fork();
        return n * f1.join();
    }
    public static void main(String[] args) {
        ForkJoinPool pool = new ForkJoinPool();
        System.out.println(pool.invoke(new Test(5)));
    }
},120,5,1,Compilation error

What is the result?
import java.util.concurrent.*;
public class Test extends RecursiveAction {
    private int n;
    public Test(int n) {
        this.n = n;
    }
    protected void compute() {
        if (n > 0) {
            System.out.println(n);
            Test task = new Test(n - 1);
            task.fork();
            task.join();
        }
    }
    public static void main(String[] args) {
        ForkJoinPool pool = new ForkJoinPool();
        pool.invoke(new Test(3));
    }
},3 2 1,1 2 3,3,Compilation error

