    protected Long compute() {
        if (n <= 1) return 1L;
        Test f1 = new Test(n - 1);
        Test f2 = new Test(n - 2);
        f1.fork();
        return f2.compute() + f1.join();
    }
    public static void main(String[] args) {
        ForkJoinPool pool = new ForkJoinPool();
        System.out.println(pool.invoke(new Test(6)));
