import java.util.concurrent.*;
public class Test extends RecursiveAction {
    private int[] arr;
    private int start, end;
    public Test(int[] arr, int start, int end) {
        this.arr = arr;
        this.start = start;
        this.end = end;
    }
    protected void compute() {
        if (end - start <= 1) {
            arr[start] *= 2;
        } else {
            int mid = (start + end) / 2;
            invokeAll(new Test(arr, start, mid), new Test(arr, mid, end));
        }
    }
    public static void main(String[] args) {
        int[] arr = {1, 2, 3, 4};
        ForkJoinPool pool = new ForkJoinPool();
        pool.invoke(new Test(arr, 0, arr.length));
        System.out.println(arr[0] + arr[3]);
    }
